// Melody grammar.
//
// NOTE: the declaration order of the (non-silent) rules below matters, since
// parse errors list the expected rules sorted by declaration order.

WHITESPACE = _{ " " | "\t" | "\n" }
COMMENT    = _{ "/*" ~ (!"*/" ~ ANY)* ~ "*/" }

// ---- quantities ----

amount = @{ ASCII_DIGIT+ }
some   = { "some" }
any    = { "any" }
option = { "option" }
over   = { "over" ~ amount }

// ---- character ranges / classes ----

ascii_range_end   = { ASCII }
class_content     = { class_char+ }
ascii_range_start = { ASCII }

class_char = _{
    ASCII_ALPHANUMERIC
  | "_" | "!" | "#" | "$" | "%" | "&" | "*" | "@" | "\\" | "^"
}

// ---- assertions ----

assertion_type = { "ahead" | "behind" }

// ---- literals ----

literal = @{
    ("\"" ~ double_quoted_char* ~ "\"")
  | ("'" ~ single_quoted_char* ~ "'")
}

double_quoted_char = _{
    !("\"" | "\\") ~ ANY
  | "\\" ~ ("\"" | "\\" | "/" | "b" | "f" | "n" | "r" | "t")
  | "\\" ~ "u" ~ ASCII_HEX_DIGIT{4}
}

single_quoted_char = _{
    !("'" | "\\") ~ ANY
  | "\\" ~ ("'" | "\\" | "/" | "b" | "f" | "n" | "r" | "t")
  | "\\" ~ "u" ~ ASCII_HEX_DIGIT{4}
}

raw = @{ "`" ~ raw_char* ~ "`" }

raw_char = _{
    !("`" | "\\") ~ ANY
  | "\\" ~ ("`" | "\\")
}

// ---- negation ----

not = { "not" }

range = {
    not? ~ (
        (amount ~ "to" ~ amount)
      | (ascii_range_start ~ "to" ~ ascii_range_end)
    )
}

// ---- quantifiers ----

quantifier_range    = { amount ~ "to" ~ amount }
quantifier_quantity = { "lazy"? ~ (quantifier_range | amount | some | any | option | over) ~ "of" }

// ---- declarations ----

group_declaration     = { (("capture" ~ identifier?) | "match" | "either") ~ block }
assertion_declaration = { not? ~ assertion_type ~ block }
variable_declaration  = { "let" ~ "." ~ identifier ~ "=" ~ block }
variable_invocation   = { "." ~ identifier }

block = { "{" ~ expression+ ~ "}" }

identifier        = { (ASCII_ALPHA | "_")+ }
symbol_identifier = { (ASCII_ALPHA | "_" | ":")+ }

// ---- structure ----

symbol         = { not? ~ "<" ~ symbol_identifier ~ ">" }
negative_class = { not ~ class_content }

quantifier = {
    quantifier_quantity ~ (
        group_declaration
      | assertion_declaration
      | variable_declaration
      | (quantifiable ~ ";")
    )
}

quantifiable = _{
    literal
  | range
  | negative_class
  | symbol
  | raw
  | variable_invocation
}

expression = _{
    quantifier
  | group_declaration
  | assertion_declaration
  | variable_declaration
  | (quantifiable ~ ";")
}

root = { SOI ~ expression* ~ EOI }
EOF
echo done"}

