use std::fmt;

/// Errors that can occur while compiling Melody source.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CompilerError {
    /// A syntax error, holding the formatted parser message.
    ParseError(String),
    InvalidQuantifierRange,
    CouldNotParseAmount,
    NegativeCharNotAllowed,
    NegativeStartNotAllowed,
    NegativeEndNotAllowed,
    UnrecognizedSymbol,
    UnrecognizedUnicodeCategory,
    UnrecognizedSymbolNamespace,
    UnexpectedAssertionInQuantifier,
    UnexpectedSpecialSymbolInQuantifier,
    UnexpectedVariableInvocationInQuantifier,
    UnexpectedSkippedNodeInQuantifier,
    UninitializedVariable,
}

impl fmt::Display for CompilerError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let message = match self {
            CompilerError::ParseError(message) => return f.write_str(message),
            CompilerError::InvalidQuantifierRange => "usage of an invalid quantifier range",
            CompilerError::CouldNotParseAmount => "could not parse an amount",
            CompilerError::NegativeCharNotAllowed => "negative char not allowed",
            CompilerError::NegativeStartNotAllowed => "negative start not allowed",
            CompilerError::NegativeEndNotAllowed => "negative end not allowed",
            CompilerError::UnrecognizedSymbol => "usage of an unrecognized symbol",
            CompilerError::UnrecognizedUnicodeCategory => {
                "usage of an unrecognized unicode category"
            }
            CompilerError::UnrecognizedSymbolNamespace => {
                "usage of an unrecognized symbol namespace"
            }
            CompilerError::UnexpectedAssertionInQuantifier => "unexpected assertion in quantifier",
            CompilerError::UnexpectedSpecialSymbolInQuantifier => {
                "unexpected special symbol in quantifier"
            }
            CompilerError::UnexpectedVariableInvocationInQuantifier => {
                "unexpected variable invocation in quantifier"
            }
            CompilerError::UnexpectedSkippedNodeInQuantifier => {
                "unexpected skipped node in quantifier"
            }
            CompilerError::UninitializedVariable => "usage of an uninitialized variable",
        };
        f.write_str(message)
    }
}

impl std::error::Error for CompilerError {}
