/// Normalizes line endings and turns `//` line comments (comments that occupy
/// a whole line) into block comments understood by the grammar.
pub fn convert_line_comments(source: &str) -> String {
    source
        .lines()
        .map(|line| {
            let trimmed = line.trim_start();
            match trimmed.strip_prefix("//") {
                Some(rest) => format!("/*{rest}*/"),
                None => line.to_owned(),
            }
        })
        .collect::<Vec<String>>()
        .join("\n")
}
