use super::errors::CompilerError;

/// The result of resolving a `<symbol>`.
pub enum ResolvedSymbol {
    /// A regular symbol, usable anywhere.
    Regular(String),
    /// A special symbol (`<start>` / `<end>`), which cannot be quantified.
    Special(String),
}

/// Resolves a symbol identifier (the text between `<` and `>`).
pub fn resolve(identifier: &str, negative: bool) -> Result<ResolvedSymbol, CompilerError> {
    if let Some((namespace, name)) = identifier.split_once("::") {
        return resolve_namespaced(namespace, name, negative).map(ResolvedSymbol::Regular);
    }

    let (positive, negated) = match identifier {
        "start" => {
            if negative {
                return Err(CompilerError::NegativeStartNotAllowed);
            }
            return Ok(ResolvedSymbol::Special("^".to_owned()));
        }
        "end" => {
            if negative {
                return Err(CompilerError::NegativeEndNotAllowed);
            }
            return Ok(ResolvedSymbol::Special("$".to_owned()));
        }
        "char" => {
            if negative {
                return Err(CompilerError::NegativeCharNotAllowed);
            }
            return Ok(ResolvedSymbol::Regular(".".to_owned()));
        }
        "whitespace" => (r"\s", r"\S"),
        "space" => (" ", "[^ ]"),
        "newline" => (r"\n", r"[^\n]"),
        "tab" => (r"\t", r"[^\t]"),
        "return" => (r"\r", r"[^\r]"),
        "feed" => (r"\f", r"[^\f]"),
        "null" => (r"\0", r"[^\0]"),
        "digit" => (r"\d", r"\D"),
        "vertical" => (r"\v", r"[^\v]"),
        "word" => (r"\w", r"\W"),
        "alphabetic" => ("[a-zA-Z]", "[^a-zA-Z]"),
        "alphanumeric" => ("[a-zA-Z0-9]", "[^a-zA-Z0-9]"),
        "boundary" => (r"\b", r"\B"),
        "backspace" => (r"[\b]", r"[^\b]"),
        _ => return Err(CompilerError::UnrecognizedSymbol),
    };

    let value = if negative { negated } else { positive };
    Ok(ResolvedSymbol::Regular(value.to_owned()))
}

fn resolve_namespaced(namespace: &str, name: &str, negative: bool) -> Result<String, CompilerError> {
    match namespace {
        "category" => {
            let code = unicode_category(name).ok_or(CompilerError::UnrecognizedUnicodeCategory)?;
            let escape = if negative { 'P' } else { 'p' };
            Ok(format!("\\{escape}{{{code}}}"))
        }
        _ => Err(CompilerError::UnrecognizedSymbolNamespace),
    }
}

fn unicode_category(name: &str) -> Option<&'static str> {
    let code = match name {
        "cased_letter" => "L&",
        "close_punctuation" => "Pe",
        "connector_punctuation" => "Pc",
        "control" => "Cc",
        "currency_symbol" => "Sc",
        "dash_punctuation" => "Pd",
        "decimal_digit_number" => "Nd",
        "enclosing_mark" => "Me",
        "final_punctuation" => "Pf",
        "format" => "Cf",
        "initial_punctuation" => "Pi",
        "letter" => "L",
        "letter_number" => "Nl",
        "line_separator" => "Zl",
        "lowercase_letter" => "Ll",
        "mark" => "M",
        "math_symbol" => "Sm",
        "modifier_letter" => "Lm",
        "modifier_symbol" => "Sk",
        "non_spacing_mark" => "Mn",
        "number" => "N",
        "open_punctuation" => "Ps",
        "other" => "C",
        "other_letter" => "Lo",
        "other_number" => "No",
        "other_punctuation" => "Po",
        "other_symbol" => "So",
        "paragraph_separator" => "Zp",
        "private_use" => "Co",
        "punctuation" => "P",
        "separator" => "Z",
        "space_separator" => "Zs",
        "spacing_combining_mark" => "Mc",
        "surrogate" => "Cs",
        "symbol" => "S",
        "titlecase_letter" => "Lt",
        "unassigned" => "Cn",
        "uppercase_letter" => "Lu",
        _ => return None,
    };
    Some(code)
}
