use std::collections::HashMap;

use pest::iterators::{Pair, Pairs};

use super::errors::CompilerError;
use super::parser::Rule;
use super::symbols::{self, ResolvedSymbol};

/// The kind of a compiled node; used to validate quantified expressions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Kind {
    Literal,
    Raw,
    Symbol,
    SpecialSymbol,
    Range,
    NegativeClass,
    Quantifier,
    Group,
    Assertion,
    VariableInvocation,
    Skip,
}

struct Node {
    kind: Kind,
    value: String,
}

impl Node {
    fn new(kind: Kind, value: impl Into<String>) -> Self {
        Node { kind, value: value.into() }
    }
}

#[derive(Default)]
struct Generator {
    variables: HashMap<String, String>,
}

pub fn generate(mut pairs: Pairs<'_, Rule>) -> Result<String, CompilerError> {
    let mut generator = Generator::default();
    let root = pairs.next().expect("root rule");
    let mut output = String::new();
    for pair in root.into_inner() {
        if pair.as_rule() == Rule::EOI {
            continue;
        }
        let node = generator.expression(pair)?;
        output.push_str(&node.value);
    }
    Ok(output)
}

/// Characters which have a special meaning in regular expressions and must
/// therefore be escaped when they appear in a literal.
const SPECIAL_CHARACTERS: &[char] = &[
    '.', '*', '+', '?', '(', ')', '[', ']', '{', '}', '|', '^', '$',
];

fn escape_literal(content: &str) -> String {
    let mut escaped = String::with_capacity(content.len());
    for character in content.chars() {
        if SPECIAL_CHARACTERS.contains(&character) {
            escaped.push('\\');
        }
        escaped.push(character);
    }
    escaped
}

/// Whether a quantified value can be quantified directly, without wrapping it
/// in a non-capturing group.
fn is_quantifiable_unit(value: &str) -> bool {
    let count = value.chars().count();
    count == 1
        || (count == 2 && value.starts_with('\\'))
        || (count > 2 && value.starts_with('[') && value.ends_with(']'))
        || (count > 2 && value.starts_with('(') && value.ends_with(')'))
}

fn first_char(pair: &Pair<'_, Rule>) -> char {
    pair.as_str().chars().next().unwrap_or_default()
}

impl Generator {
    fn expression(&mut self, pair: Pair<'_, Rule>) -> Result<Node, CompilerError> {
        match pair.as_rule() {
            Rule::quantifier => self.quantifier(pair),
            Rule::group_declaration => self.group(pair),
            Rule::assertion_declaration => self.assertion(pair),
            Rule::variable_declaration => self.variable_declaration(pair),
            Rule::variable_invocation => self.variable_invocation(pair),
            Rule::literal => Ok(Self::literal(pair)),
            Rule::raw => Ok(Self::raw(pair)),
            Rule::range => Ok(Self::range(pair)),
            Rule::negative_class => Ok(Self::negative_class(pair)),
            Rule::symbol => Self::symbol(pair),
            rule => unreachable!("unexpected rule {rule:?}"),
        }
    }

    fn block(&mut self, pair: Pair<'_, Rule>) -> Result<Vec<Node>, CompilerError> {
        pair.into_inner().map(|statement| self.expression(statement)).collect()
    }

    fn quantifier(&mut self, pair: Pair<'_, Rule>) -> Result<Node, CompilerError> {
        let mut inner = pair.into_inner();
        let quantity = inner.next().expect("quantifier quantity");
        let body = inner.next().expect("quantified expression");

        let node = self.expression(body)?;
        match node.kind {
            Kind::Assertion => return Err(CompilerError::UnexpectedAssertionInQuantifier),
            Kind::SpecialSymbol => return Err(CompilerError::UnexpectedSpecialSymbolInQuantifier),
            Kind::VariableInvocation => {
                return Err(CompilerError::UnexpectedVariableInvocationInQuantifier)
            }
            Kind::Skip => return Err(CompilerError::UnexpectedSkippedNodeInQuantifier),
            _ => {}
        }

        let lazy = quantity.as_str().starts_with("lazy");
        let kind = quantity.into_inner().next().expect("quantity kind");
        let mut suffix = match kind.as_rule() {
            Rule::quantifier_range => {
                let mut amounts = kind.into_inner();
                let start = amounts.next().expect("range start").as_str();
                let end = amounts.next().expect("range end").as_str();
                match (start.parse::<usize>(), end.parse::<usize>()) {
                    (Ok(start_value), Ok(end_value)) if start_value <= end_value => {}
                    _ => return Err(CompilerError::InvalidQuantifierRange),
                }
                format!("{{{start},{end}}}")
            }
            Rule::amount => format!("{{{}}}", kind.as_str()),
            Rule::some => "+".to_owned(),
            Rule::any => "*".to_owned(),
            Rule::option => "?".to_owned(),
            Rule::over => {
                let amount = kind.into_inner().next().expect("over amount").as_str();
                let value = amount
                    .parse::<usize>()
                    .ok()
                    .and_then(|value| value.checked_add(1))
                    .ok_or(CompilerError::CouldNotParseAmount)?;
                format!("{{{value},}}")
            }
            rule => unreachable!("unexpected quantity {rule:?}"),
        };
        if lazy {
            suffix.push('?');
        }

        let value = if node.kind == Kind::Symbol || is_quantifiable_unit(&node.value) {
            node.value
        } else {
            format!("(?:{})", node.value)
        };

        Ok(Node::new(Kind::Quantifier, format!("{value}{suffix}")))
    }

    fn group(&mut self, pair: Pair<'_, Rule>) -> Result<Node, CompilerError> {
        let text = pair.as_str();
        let mut name = None;
        let mut statements = Vec::new();
        for child in pair.into_inner() {
            match child.as_rule() {
                Rule::identifier => name = Some(child.as_str().to_owned()),
                Rule::block => statements = self.block(child)?,
                rule => unreachable!("unexpected group child {rule:?}"),
            }
        }

        let value = if text.starts_with("capture") {
            let content: String = statements.iter().map(|node| node.value.as_str()).collect();
            match name {
                Some(name) => format!("(?<{name}>{content})"),
                None => format!("({content})"),
            }
        } else if text.starts_with("either") {
            let alternatives: Vec<&str> = statements.iter().map(|node| node.value.as_str()).collect();
            format!("(?:{})", alternatives.join("|"))
        } else {
            let content: String = statements.iter().map(|node| node.value.as_str()).collect();
            format!("(?:{content})")
        };

        Ok(Node::new(Kind::Group, value))
    }

    fn assertion(&mut self, pair: Pair<'_, Rule>) -> Result<Node, CompilerError> {
        let mut negative = false;
        let mut behind = false;
        let mut statements = Vec::new();
        for child in pair.into_inner() {
            match child.as_rule() {
                Rule::not => negative = true,
                Rule::assertion_type => behind = child.as_str() == "behind",
                Rule::block => statements = self.block(child)?,
                rule => unreachable!("unexpected assertion child {rule:?}"),
            }
        }
        let content: String = statements.iter().map(|node| node.value.as_str()).collect();
        let prefix = match (behind, negative) {
            (false, false) => "?=",
            (false, true) => "?!",
            (true, false) => "?<=",
            (true, true) => "?<!",
        };
        Ok(Node::new(Kind::Assertion, format!("({prefix}{content})")))
    }

    fn variable_declaration(&mut self, pair: Pair<'_, Rule>) -> Result<Node, CompilerError> {
        let mut inner = pair.into_inner();
        let name = inner.next().expect("variable name").as_str().to_owned();
        let block = inner.next().expect("variable block");
        let statements = self.block(block)?;
        let content: String = statements.iter().map(|node| node.value.as_str()).collect();
        self.variables.insert(name, content);
        Ok(Node::new(Kind::Skip, ""))
    }

    fn variable_invocation(&mut self, pair: Pair<'_, Rule>) -> Result<Node, CompilerError> {
        let name = pair.into_inner().next().expect("variable name").as_str();
        let value = self
            .variables
            .get(name)
            .ok_or(CompilerError::UninitializedVariable)?
            .clone();
        Ok(Node::new(Kind::VariableInvocation, value))
    }

    fn literal(pair: Pair<'_, Rule>) -> Node {
        let text = pair.as_str();
        let quote = &text[..1];
        let content = &text[1..text.len() - 1];
        let unescaped = content.replace(&format!("\\{quote}"), quote);
        Node::new(Kind::Literal, escape_literal(&unescaped))
    }

    fn raw(pair: Pair<'_, Rule>) -> Node {
        let text = pair.as_str();
        let content = &text[1..text.len() - 1];
        Node::new(Kind::Raw, content.replace("\\`", "`"))
    }

    fn range(pair: Pair<'_, Rule>) -> Node {
        let mut negative = false;
        let mut bounds = Vec::with_capacity(2);
        for child in pair.into_inner() {
            match child.as_rule() {
                Rule::not => negative = true,
                _ => bounds.push(first_char(&child)),
            }
        }
        let negation = if negative { "^" } else { "" };
        Node::new(Kind::Range, format!("[{negation}{}-{}]", bounds[0], bounds[1]))
    }

    fn negative_class(pair: Pair<'_, Rule>) -> Node {
        let content = pair
            .into_inner()
            .find(|child| child.as_rule() == Rule::class_content)
            .map(|child| child.as_str())
            .unwrap_or_default();
        Node::new(Kind::NegativeClass, format!("[^{content}]"))
    }

    fn symbol(pair: Pair<'_, Rule>) -> Result<Node, CompilerError> {
        let mut negative = false;
        let mut identifier = "";
        for child in pair.into_inner() {
            match child.as_rule() {
                Rule::not => negative = true,
                Rule::symbol_identifier => identifier = child.as_str(),
                rule => unreachable!("unexpected symbol child {rule:?}"),
            }
        }
        match symbols::resolve(identifier, negative)? {
            ResolvedSymbol::Regular(value) => Ok(Node::new(Kind::Symbol, value)),
            ResolvedSymbol::Special(value) => Ok(Node::new(Kind::SpecialSymbol, value)),
        }
    }
}
