                .action(ArgAction::Set)
                .conflicts_with_all([
                    ids::INPUT_FILE_PATH,
                    ids::OUTPUT_FILE_PATH,
                    ids::REPL,
                    ids::TEST,
                    ids::TEST_FILE,
                ]),
        )
        .arg(
            Arg::new(ids::TEST)
                .short('t')
                .long("test")
                .value_name("test")
                .help("Test the compiled regex against a string")
                .action(ArgAction::Set)
                .conflicts_with_all([ids::OUTPUT_FILE_PATH, ids::REPL, ids::TEST_FILE]),
        )
        .arg(
            Arg::new(ids::TEST_FILE)
                .short('f')
                .long("test-file")
                .value_name("test-file")
                .help("Test the compiled regex against the contents of a file")
                .action(ArgAction::Set)
                .conflicts_with_all([ids::OUTPUT_FILE_PATH, ids::REPL, ids::TEST]),
        )
        .group(ArgGroup::new("Args").multiple(true).args([
            ids::INPUT_FILE_PATH,
            ids::OUTPUT_FILE_PATH,
            ids::NO_COLOR,
            ids::REPL,
            ids::COMPLETIONS,
            ids::TEST,
            ids::TEST_FILE,
        ]))
}

/// Parsed command line arguments.
pub struct Args {
    pub input_file_path: Option<String>,
    pub output_file_path: Option<String>,
    pub no_color: bool,
    pub repl: bool,
    pub completions: Option<String>,
    pub test: Option<String>,
    pub test_file: Option<String>,
}

impl Args {
    pub fn parse() -> Self {
        let matches = command().get_matches();
        let string = |id: &str| matches.get_one::<String>(id).cloned();
        Args {
            input_file_path: string(ids::INPUT_FILE_PATH),
            output_file_path: string(ids::OUTPUT_FILE_PATH),
            no_color: matches.get_flag(ids::NO_COLOR),
            repl: matches.get_flag(ids::REPL),
            completions: string(ids::COMPLETIONS),
            test: string(ids::TEST),
            test_file: string(ids::TEST_FILE),
        }
    }
}
