    pub fn exit_code(&self) -> u8 {
        match self {
            CliError::ReadInputFile(_) => EX_DATAERR,
            CliError::ReadTestFile(_) => EX_IOERR,
            CliError::ReadStdin => EX_DATAERR,
            CliError::WriteFile(_) => EX_IOERR,
            CliError::NoInput => EX_NOINPUT,
            CliError::ReplWithPipe => EX_USAGE,
            CliError::Compile(_) => EX_DATAERR,
            CliError::CompileRegex { .. } => EX_DATAERR,
        }
    }

    fn message(&self) -> String {
        match self {
            CliError::ReadInputFile(path) | CliError::ReadTestFile(path) => {
                format!("unable read file at path {path}")
            }
            CliError::ReadStdin => "unable to read stdin".to_owned(),
