/// A set of code point ranges, optionally inverted.
#[derive(Debug, Clone, Default)]
pub struct CharSet {
    pub ranges: Vec<(u32, u32)>,
    pub inverted: bool,
}

impl CharSet {
    pub fn add(&mut self, start: u32, end: u32) {
        self.ranges.push((start, end));
    }

    pub fn add_set(&mut self, other: &[(u32, u32)]) {
        self.ranges.extend_from_slice(other);
    }

    /// Adds the complement of the given (sorted, non-overlapping) ranges.
    pub fn add_complement(&mut self, other: &[(u32, u32)]) {
        let mut next = 0u32;
        for &(start, end) in other {
            if start > next {
                self.ranges.push((next, start - 1));
            }
            next = end + 1;
        }
        if next <= 0x10FFFF {
            self.ranges.push((next, 0x10FFFF));
        }
    }

    pub fn contains(&self, c: u32) -> bool {
        let found = self.ranges.iter().any(|&(start, end)| start <= c && c <= end);
        found != self.inverted
    }
}

#[derive(Debug, Clone)]
pub enum Node {
