//! A small backtracking regular expression engine implementing ECMAScript
//! regular expression syntax and semantics (without flags), used to test
//! compiled Melody output against strings.

mod exec;
mod ir;
mod parse;
mod unicode;

use std::fmt;

/// An error encountered while compiling a regular expression.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    text: String,
}

impl Error {
    fn new(text: impl Into<String>) -> Self {
        Error { text: text.into() }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

impl std::error::Error for Error {}

/// A compiled regular expression.
#[derive(Debug, Clone)]
pub struct Regex {
    root: ir::Node,
}

impl Regex {
    /// Compiles a pattern using ECMAScript syntax with no flags.
    pub fn new(pattern: &str) -> Result<Regex, Error> {
        let root = parse::parse(pattern)?;
        Ok(Regex { root })
    }

    /// Returns whether the regular expression matches anywhere in `text`.
    pub fn is_match(&self, text: &str) -> bool {
        exec::is_match(&self.root, text)
    }
}
