//! Parser for ECMAScript regular expressions (no flags, with the Annex B
//! extensions for web compatibility).

use std::collections::HashSet;

use super::ir::{CharSet, Node};
use super::unicode;
use super::Error;

const UNBALANCED_PARENTHESIS: &str = "unbalanced parenthesis";
const UNBALANCED_BRACKET: &str = "unbalanced bracket";
const INVALID_ATOM_CHARACTER: &str = "invalid atom character";
const INVALID_QUANTIFIER: &str = "invalid quantifier";
const INVALID_BRACED_QUANTIFIER: &str = "invalid braced quantifier";
const QUANTIFIER_NOT_ALLOWED: &str = "quantifier not allowed here";
const RANGE_REVERSED: &str =
    "range values reversed, start char code is greater than end char code.";
const DUPLICATE_GROUP_NAME: &str = "duplicate capture group name";
const INVALID_GROUP_NAME: &str = "invalid token at named capture group identifier";
const INCOMPLETE_ESCAPE: &str = "incomplete escape";

/// A single element of a character class.
enum ClassAtom {
    CodePoint(u32),
    Set(Vec<(u32, u32)>),
}

struct Quantifier {
    min: usize,
    max: usize,
    greedy: bool,
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
    group_count: usize,
}

pub fn parse(pattern: &str) -> Result<Node, Error> {
    let mut parser = Parser { chars: pattern.chars().collect(), pos: 0, group_count: 0 };
    parser.scan_named_groups()?;
    let node = parser.disjunction()?;
    match parser.peek() {
        None => Ok(node),
        Some(')') => Err(Error::new(UNBALANCED_PARENTHESIS)),
        Some(c) => Err(Error::new(format!("unexpected char: {c}"))),
    }
}

fn hex_value(c: Option<char>) -> Option<u32> {
    c.and_then(|c| c.to_digit(16))
}

fn is_octal_digit(c: Option<char>) -> bool {
    matches!(c, Some('0'..='7'))
}

impl Parser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn try_consume(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn try_consume_str(&mut self, s: &str) -> bool {
        let start = self.pos;
        for c in s.chars() {
            if !self.try_consume(c) {
                self.pos = start;
                return false;
            }
        }
        true
    }

    /// Pre-scans the pattern for named capture groups, rejecting duplicate
    /// names before the pattern is parsed.
    fn scan_named_groups(&mut self) -> Result<(), Error> {
        let start = self.pos;
        let mut names = HashSet::new();
        let mut in_class = false;
        while let Some(c) = self.next() {
            match c {
                '\\' => {
                    self.next();
                }
                '[' => in_class = true,
                ']' => in_class = false,
                '(' if !in_class => {
                    if self.peek() == Some('?')
                        && self.peek_at(1) == Some('<')
                        && !matches!(self.peek_at(2), Some('=') | Some('!'))
                    {
                        self.pos += 2;
                        if let Some(name) = self.group_name() {
                            if !names.insert(name) {
                                return Err(Error::new(DUPLICATE_GROUP_NAME));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        self.pos = start;
        Ok(())
    }

    /// Parses a group name followed by `>`. On failure, the position is left
    /// at the offending character.
    fn group_name(&mut self) -> Option<String> {
        let mut name = String::new();
        loop {
            let save = self.pos;
            let c = match self.peek() {
                Some('>') if !name.is_empty() => {
                    self.pos += 1;
                    return Some(name);
                }
                Some('\\') => {
                    self.pos += 1;
                    if !self.try_consume('u') {
                        self.pos = save;
                        return None;
                    }
                    match self.unicode_escape_digits() {
                        Some(value) => match char::from_u32(value) {
                            Some(c) => c,
                            None => {
                                self.pos = save;
                                return None;
                            }
                        },
                        None => {
                            self.pos = save;
                            return None;
                        }
                    }
                }
                Some(c) => {
                    self.pos += 1;
                    c
                }
                None => return None,
            };
            let valid = if name.is_empty() {
                unicode::is_id_start(c)
            } else {
                unicode::is_id_continue(c)
            };
            if !valid {
                self.pos = save;
                return None;
            }
            name.push(c);
        }
    }

    /// Parses exactly four hex digits, restoring the position on failure.
    fn unicode_escape_digits(&mut self) -> Option<u32> {
        let start = self.pos;
        let mut value = 0;
        for _ in 0..4 {
            match hex_value(self.next()) {
                Some(digit) => value = value * 16 + digit,
                None => {
                    self.pos = start;
                    return None;
                }
            }
        }
        Some(value)
    }

    fn disjunction(&mut self) -> Result<Node, Error> {
        let mut alternatives = vec![self.alternative()?];
        while self.try_consume('|') {
            alternatives.push(self.alternative()?);
        }
        if alternatives.len() == 1 {
            Ok(alternatives.pop().unwrap_or(Node::Empty))
        } else {
            Ok(Node::Alt(alternatives))
        }
    }

    fn alternative(&mut self) -> Result<Node, Error> {
        let mut terms = Vec::new();
        loop {
            let c = match self.peek() {
                None | Some(')') | Some('|') => break,
                Some(c) => c,
            };
            let mut quantifier_allowed = true;
            let atom = match c {
                '^' => {
                    self.pos += 1;
                    quantifier_allowed = false;
                    Node::StartOfInput
                }
                '$' => {
                    self.pos += 1;
                    quantifier_allowed = false;
                    Node::EndOfInput
                }
                '\\' => {
                    self.pos += 1;
                    match self.peek() {
                        Some('b') => {
                            self.pos += 1;
                            Node::WordBoundary { negated: false }
                        }
                        Some('B') => {
                            self.pos += 1;
                            Node::WordBoundary { negated: true }
                        }
                        Some(_) => self.atom_escape()?,
                        None => return Err(Error::new(INCOMPLETE_ESCAPE)),
                    }
                }
                '.' => {
                    self.pos += 1;
                    Node::AnyExceptLineTerminator
                }
                '(' => {
                    let (node, quantifiable) = self.group()?;
                    quantifier_allowed = quantifiable;
                    node
                }
                '[' => self.class()?,
                '*' | '+' | '?' => return Err(Error::new(INVALID_ATOM_CHARACTER)),
                '{' => {
                    let start = self.pos;
                    if self.braced_quantifier().is_some() {
                        return Err(Error::new(INVALID_BRACED_QUANTIFIER));
                    }
                    self.pos = start + 1;
                    Node::Char('{' as u32)
                }
                c => {
                    self.pos += 1;
                    Node::Char(c as u32)
                }
            };

            let node = match self.quantifier() {
                Some(quantifier) => {
                    if !quantifier_allowed {
                        return Err(Error::new(QUANTIFIER_NOT_ALLOWED));
                    }
                    if quantifier.min > quantifier.max {
                        return Err(Error::new(INVALID_QUANTIFIER));
                    }
                    Node::Repeat {
                        node: Box::new(atom),
                        min: quantifier.min,
                        max: quantifier.max,
                        greedy: quantifier.greedy,
                    }
                }
                None => atom,
            };
            terms.push(node);
        }
        Ok(match terms.len() {
            0 => Node::Empty,
            1 => terms.pop().unwrap_or(Node::Empty),
            _ => Node::Cat(terms),
        })
    }

    fn quantifier(&mut self) -> Option<Quantifier> {
        let (min, max) = match self.peek() {
            Some('*') => {
                self.pos += 1;
                (0, usize::MAX)
            }
            Some('+') => {
                self.pos += 1;
                (1, usize::MAX)
            }
            Some('?') => {
                self.pos += 1;
                (0, 1)
            }
            Some('{') => self.braced_quantifier()?,
            _ => return None,
        };
        let greedy = !self.try_consume('?');
        Some(Quantifier { min, max, greedy })
    }

    /// Parses `{n}`, `{n,}` or `{n,m}`, restoring the position on failure.
    fn braced_quantifier(&mut self) -> Option<(usize, usize)> {
        let start = self.pos;
        let result = (|| {
            if !self.try_consume('{') {
                return None;
            }
            let min = self.decimal()?;
            let mut max = min;
            if self.try_consume(',') {
                max = self.decimal().unwrap_or(usize::MAX);
            }
            if !self.try_consume('}') {
                return None;
            }
            Some((min, max))
        })();
        if result.is_none() {
            self.pos = start;
        }
        result
    }

    fn decimal(&mut self) -> Option<usize> {
        let mut value: usize = 0;
        let mut digits = 0;
        while let Some(digit) = self.peek().and_then(|c| c.to_digit(10)) {
            self.pos += 1;
            digits += 1;
            value = value.saturating_mul(10).saturating_add(digit as usize);
        }
        if digits > 0 {
            Some(value)
        } else {
            None
        }
    }

    /// Parses a group starting at `(`. Returns the node and whether it may be
    /// quantified.
    fn group(&mut self) -> Result<(Node, bool), Error> {
        let (node, quantifiable) = if self.try_consume_str("(?=") {
            let body = self.disjunction()?;
            (Node::LookAround { behind: false, negated: false, node: Box::new(body) }, true)
        } else if self.try_consume_str("(?!") {
            let body = self.disjunction()?;
            (Node::LookAround { behind: false, negated: true, node: Box::new(body) }, true)
        } else if self.try_consume_str("(?<=") {
            let body = self.disjunction()?;
            (Node::LookAround { behind: true, negated: false, node: Box::new(body) }, false)
        } else if self.try_consume_str("(?<!") {
            let body = self.disjunction()?;
            (Node::LookAround { behind: true, negated: true, node: Box::new(body) }, false)
        } else if self.try_consume_str("(?:") {
            let body = self.disjunction()?;
            (Node::Group(Box::new(body)), true)
        } else if self.try_consume_str("(?") {
            if !self.try_consume('<') || self.group_name().is_none() {
                return Err(Error::new(INVALID_GROUP_NAME));
            }
            self.group_count += 1;
            let body = self.disjunction()?;
            (Node::Group(Box::new(body)), true)
        } else {
            self.pos += 1;
            self.group_count += 1;
            let body = self.disjunction()?;
            (Node::Group(Box::new(body)), true)
        };
        if !self.try_consume(')') {
            return Err(Error::new(UNBALANCED_PARENTHESIS));
        }
        Ok((node, quantifiable))
    }

    /// Parses an escape (after the backslash) outside of a character class.
    fn atom_escape(&mut self) -> Result<Node, Error> {
        let c = match self.peek() {
            Some(c) => c,
            None => return Err(Error::new(INCOMPLETE_ESCAPE)),
        };
        if let Some(set) = class_escape_set(c) {
            self.pos += 1;
            return Ok(Node::Set(set));
        }
        if let Some('1'..='9') = Some(c) {
            let start = self.pos;
            let number = self.decimal().unwrap_or(0);
            if number <= self.group_count_total() {
                return Ok(Node::BackReference(number));
            }
            self.pos = start;
            if c >= '8' {
                self.pos += 1;
                return Ok(Node::Char(c as u32));
            }
            return Ok(Node::Char(self.legacy_octal()));
        }
        Ok(Node::Char(self.character_escape(false)))
    }

    fn group_count_total(&self) -> usize {
        // Count all capturing groups in the pattern.
        let mut count = 0;
        let mut in_class = false;
        let mut i = 0;
        while i < self.chars.len() {
            match self.chars[i] {
                '\\' => i += 1,
                '[' => in_class = true,
                ']' => in_class = false,
                '(' if !in_class => {
                    let next = self.chars.get(i + 1).copied();
                    if next != Some('?') {
                        count += 1;
                    } else if self.chars.get(i + 2) == Some(&'<')
                        && !matches!(self.chars.get(i + 3), Some('=') | Some('!'))
                    {
                        count += 1;
                    }
                }
                _ => {}
            }
            i += 1;
        }
        count
    }

    /// Parses a legacy octal escape (Annex B), starting at the first digit.
    fn legacy_octal(&mut self) -> u32 {
        let first = self.next().and_then(|c| c.to_digit(8)).unwrap_or(0);
        let mut value = first;
        if is_octal_digit(self.peek()) {
            value = value * 8 + self.next().and_then(|c| c.to_digit(8)).unwrap_or(0);
            if first <= 3 && is_octal_digit(self.peek()) {
                value = value * 8 + self.next().and_then(|c| c.to_digit(8)).unwrap_or(0);
            }
        }
        value
    }

    /// Parses a character escape (after the backslash), returning its value.
    fn character_escape(&mut self, in_class: bool) -> u32 {
        let c = match self.next() {
            Some(c) => c,
            None => return '\\' as u32,
        };
        match c {
            'f' => 0x0C,
            'n' => 0x0A,
            'r' => 0x0D,
            't' => 0x09,
            'v' => 0x0B,
            'c' => {
                let control = self.peek().filter(|c| {
                    c.is_ascii_alphabetic() || (in_class && (c.is_ascii_digit() || *c == '_'))
                });
                match control {
                    Some(letter) => {
                        self.pos += 1;
                        (letter as u32) % 32
                    }
                    None => {
                        // The backslash is a literal; `c` is parsed next.
                        self.pos -= 1;
                        '\\' as u32
                    }
                }
            }
            '0'..='7' => {
                self.pos -= 1;
                if c == '0' && !self.peek_at(1).is_some_and(|d| d.is_ascii_digit()) {
                    self.pos += 1;
                    return 0;
                }
                self.legacy_octal()
            }
            'x' => {
                let high = hex_value(self.next());
                let low = hex_value(self.next());
                match (high, low) {
                    (Some(high), Some(low)) => high * 16 + low,
                    _ => 'x' as u32,
                }
            }
            'u' => self.unicode_escape_digits().unwrap_or('u' as u32),
            other => other as u32,
        }
    }

    fn class(&mut self) -> Result<Node, Error> {
        self.pos += 1;
        let mut set = CharSet { ranges: Vec::new(), inverted: self.try_consume('^') };
        loop {
            match self.peek() {
                None => return Err(Error::new(UNBALANCED_BRACKET)),
                Some(']') => {
                    self.pos += 1;
                    break;
                }
                Some(_) => {}
            }
            let first = self.class_atom()?;
            if self.peek() == Some('-') && self.peek_at(1).is_some_and(|c| c != ']') {
                self.pos += 1;
                let second = self.class_atom()?;
                match (first, second) {
                    (ClassAtom::CodePoint(start), ClassAtom::CodePoint(end)) => {
                        if start > end {
                            return Err(Error::new(RANGE_REVERSED));
                        }
                        set.add(start, end);
                    }
                    (first, second) => {
                        add_atom(&mut set, first);
                        set.add('-' as u32, '-' as u32);
                        add_atom(&mut set, second);
                    }
                }
            } else {
                add_atom(&mut set, first);
            }
        }
        Ok(Node::Set(set))
    }

    fn class_atom(&mut self) -> Result<ClassAtom, Error> {
        let c = match self.next() {
            Some(c) => c,
            None => return Err(Error::new(UNBALANCED_BRACKET)),
        };
        if c != '\\' {
            return Ok(ClassAtom::CodePoint(c as u32));
        }
        let escaped = match self.peek() {
            Some(escaped) => escaped,
            None => return Err(Error::new(UNBALANCED_BRACKET)),
        };
        if let Some(set) = class_escape_set(escaped) {
            self.pos += 1;
            return Ok(ClassAtom::Set(set.ranges_with_inversion()));
        }
        match escaped {
            'b' => {
                self.pos += 1;
                Ok(ClassAtom::CodePoint(0x08))
            }
            '-' => {
                self.pos += 1;
                Ok(ClassAtom::CodePoint('-' as u32))
            }
            '8' | '9' => {
                self.pos += 1;
                Ok(ClassAtom::CodePoint(escaped as u32))
            }
            _ => Ok(ClassAtom::CodePoint(self.character_escape(true))),
        }
    }
}

fn add_atom(set: &mut CharSet, atom: ClassAtom) {
    match atom {
        ClassAtom::CodePoint(c) => set.add(c, c),
        ClassAtom::Set(ranges) => set.add_set(&ranges),
    }
}

/// Returns the set for a character class escape (`\d`, `\s`, `\w` and their
/// negations).
fn class_escape_set(c: char) -> Option<CharSet> {
    let (ranges, inverted) = match c {
        'd' => (unicode::DIGITS, false),
        'D' => (unicode::DIGITS, true),
        's' => (unicode::WHITESPACE, false),
        'S' => (unicode::WHITESPACE, true),
        'w' => (unicode::WORD_CHARS, false),
        'W' => (unicode::WORD_CHARS, true),
        _ => return None,
    };
    let mut set = CharSet::default();
    if inverted {
        set.add_complement(ranges);
    } else {
        set.add_set(ranges);
    }
    Some(set)
}

impl CharSet {
    fn ranges_with_inversion(self) -> Vec<(u32, u32)> {
        self.ranges
    }
}
