//! A backtracking matcher operating on code points.

use super::ir::{CharSet, Node};
use super::unicode;

const MATCHER_STACK_SIZE: usize = 1 << 30;

pub fn is_match(root: &Node, text: &str) -> bool {
    let chars: Vec<u32> = text.chars().map(u32::from).collect();
    let search = || {
        let matcher = Matcher { text: &chars };
        (0..=chars.len()).any(|start| matcher.matches(root, start, true, &|_| true))
    };

    std::thread::scope(|scope| {
        std::thread::Builder::new()
            .stack_size(MATCHER_STACK_SIZE)
            .spawn_scoped(scope, search)
            .ok()
            .and_then(|handle| handle.join().ok())
    })
    .unwrap_or_else(|| {
        let matcher = Matcher { text: &chars };
        (0..=chars.len()).any(|start| matcher.matches(root, start, true, &|_| true))
    })
}

/// A predicate matching exactly one code point.
enum Single<'a> {
    Char(u32),
    Any,
    Set(&'a CharSet),
}

impl Single<'_> {
    fn accepts(&self, c: u32) -> bool {
        match self {
            Single::Char(expected) => c == *expected,
            Single::Any => !unicode::is_line_terminator(c),
            Single::Set(set) => set.contains(c),
        }
    }
}

fn single(node: &Node) -> Option<Single<'_>> {
    match node {
        Node::Char(c) => Some(Single::Char(*c)),
        Node::AnyExceptLineTerminator => Some(Single::Any),
        Node::Set(set) => Some(Single::Set(set)),
        Node::Group(inner) => single(inner),
        _ => None,
    }
}

/// Whether a node can only ever match the empty string.
fn is_zero_width(node: &Node) -> bool {
    match node {
        Node::Empty
        | Node::StartOfInput
        | Node::EndOfInput
        | Node::WordBoundary { .. }
        | Node::LookAround { .. } => true,
        Node::Group(inner) => is_zero_width(inner),
        Node::Cat(nodes) | Node::Alt(nodes) => nodes.iter().all(is_zero_width),
        Node::Repeat { node, .. } => is_zero_width(node),
        _ => false,
    }
}

struct Matcher<'t> {
    text: &'t [u32],
}

impl Matcher<'_> {
    /// Consumes a single code point satisfying `single` in the given
    /// direction, returning the new position.
    fn step(&self, pos: usize, forward: bool, single: &Single<'_>) -> Option<usize> {
        if forward {
            let c = *self.text.get(pos)?;
            single.accepts(c).then_some(pos + 1)
        } else {
            if pos == 0 {
                return None;
            }
            single.accepts(self.text[pos - 1]).then_some(pos - 1)
        }
    }

    fn is_word_at(&self, index: Option<usize>) -> bool {
        index
            .and_then(|index| self.text.get(index))
            .is_some_and(|&c| unicode::is_word_char(c))
