        assert_eq!(compile(r#"some of "a";"#), "a+");
        assert_eq!(compile(r#"lazy 1 to 5 of "a";"#), "a{1,5}?");
        assert_eq!(compile(r#"over 5 of "a";"#), "a{6,}");
        assert_eq!(compile("some of <word>;"), r"\w+");
    }

    #[test]
    fn groups_and_assertions() {
        assert_eq!(compile(r#"2 of match { <space>; "batman"; }"#), "(?: batman){2}");
        assert_eq!(compile(r#"capture name { "a"; }"#), "(?<name>a)");
        assert_eq!(compile(r#"either { "a"; "b"; }"#), "(?:a|b)");
        assert_eq!(compile(r#"not behind { "a"; }"#), "(?<!a)");
    }

    #[test]
    fn variables_and_comments() {
        assert_eq!(compile("let .x = { \"a\"; }\n// comment\n.x;"), "a");
